"""Article-specific editorial source for CC-07 (Civil Code arts. 371-400)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {
        "target": target,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "371": row("O devedor só compensa crédito próprio contra seu credor; o fiador pode usar crédito que tenha contra o credor do afiançado.", "A compensação exige reciprocidade entre credor e devedor. A exceção protege o fiador: cobrado pela garantia, ele pode invocar crédito que possua contra quem é credor da dívida garantida.", "Banco cobra o fiador, que demonstra possuir crédito vencido contra o próprio banco e pede sua compensação.", "O fiador usa crédito próprio, não um crédito pertencente ao afiançado. Também precisam estar presentes os demais requisitos da compensação.", "Reciprocidade", "presença de créditos e débitos opostos entre as pessoas consideradas"),
    "372": row("Prazo de favor concedido ao devedor, mesmo habitual, não impede a compensação.", "A mera tolerância que adia informalmente a cobrança não altera a exigibilidade relevante para extinguir dívidas recíprocas. O crédito continua apto a ser compensado.", "Fornecedor tolera pagamento por mais dez dias, mas antes disso compensa o débito com crédito recíproco do cliente.", "Prazo de favor não se confunde com alteração contratual válida do vencimento. É preciso verificar se houve simples tolerância ou verdadeira prorrogação.", "Prazo de favor", "tolerância concedida para pagar depois, sem modificação necessária do vencimento jurídico"),
    "373": row("A origem diferente das dívidas normalmente não impede compensação, salvo crédito ligado a esbulho, furto ou roubo, comodato, depósito, alimentos ou bem impenhorável.", "A lei exclui situações em que a restituição ou a proteção da prestação deve prevalecer. Quem detém coisa obtida ilicitamente, emprestada ou depositada não neutraliza a devolução com crédito diverso; alimentos e bens impenhoráveis recebem proteção própria.", "Depositário não pode deixar de devolver o bem alegando crédito compensável contra o depositante.", "As exceções devem ser identificadas pela causa concreta da dívida. Diferença comum de contratos, por si só, não afasta compensação.", "Causa da dívida", "relação jurídica ou fato de que nasce a obrigação"),
    "375": row("Não há compensação quando ambas as partes a excluem ou quando uma delas renuncia previamente a esse efeito.", "A compensação legal pode ser afastada pela autonomia privada. A exclusão bilateral resulta de acordo; a renúncia é a manifestação de quem abre mão de invocá-la.", "Duas empresas estipulam que créditos de contratos diferentes serão pagos separadamente, sem compensação.", "A validade e o alcance da renúncia ou da cláusula devem ser examinados. O artigo não autoriza prejudicar terceiros nem afastar normas protetivas indisponíveis.", "Renúncia", "abandono voluntário de uma faculdade ou vantagem jurídica"),
    "376": row("Quem assume obrigação por terceiro não pode compensá-la com crédito pessoal que tenha contra o credor.", "A falta de reciprocidade impede que o obrigado por dívida alheia use relação própria para extinguir o débito assumido em favor do terceiro. A obrigação considerada não nasceu como dívida pessoal contraposta ao crédito invocado.", "Pessoa promete pagar dívida de uma sociedade e tenta abater crédito particular contra o credor; a compensação é recusada.", "A regra depende da forma e do alcance da obrigação por terceiro. Não se deve confundi-la com a situação específica do fiador tratada no art. 371.", "Obrigação por terceiro", "dever assumido para satisfazer dívida atribuída a outra pessoa"),
    "377": row("O devedor notificado da cessão que não reserva compensação perde a possibilidade de opor ao cessionário crédito anterior contra o cedente; sem notificação, conserva essa defesa.", "A ciência da transferência exige que o devedor manifeste a compensação disponível. Seu silêncio protege o novo credor. Se não soube da cessão, pode contrapor ao cessionário o crédito que já possuía contra o credor original.", "Devedor é avisado da cessão e nada diz sobre crédito anterior; depois não pode usá-lo contra o cessionário.", "A regra trata do crédito existente antes da cessão. Créditos posteriores e outras exceções seguem disciplina própria.", "Cessionário", "pessoa que recebe de outra a titularidade de um crédito"),
    "378": row("Dívidas pagáveis em lugares distintos só se compensam depois de descontadas as despesas necessárias à operação.", "A compensação não deve transferir a uma parte os custos que teria evitado se o pagamento ocorresse no local convencionado. Por isso se ajusta o saldo pelas despesas indispensáveis.", "Dois pagamentos seriam feitos em cidades diferentes; ao compensá-los, deduz-se o custo necessário de remessa.", "Somente despesas necessárias e demonstráveis entram no ajuste. A regra não impede definitivamente a compensação por haver locais diferentes.", "Dedução", "subtração de valor para apurar o saldo devido"),
    "379": row("Havendo várias dívidas compensáveis da mesma pessoa, aplicam-se as regras de imputação do pagamento para definir quais serão extintas.", "A norma organiza a escolha quando o encontro de contas não basta para eliminar todos os débitos. Utilizam-se os critérios legais que determinam a qual dívida o valor será atribuído.", "Devedor possui três débitos vencidos e um crédito menor; a imputação identifica qual débito será abatido.", "Compensação e imputação não são o mesmo instituto. As regras da imputação apenas resolvem a prioridade entre múltiplas dívidas compensáveis.", "Imputação", "atribuição de um pagamento ou abatimento a determinada dívida entre várias"),
    "380": row("A compensação não pode prejudicar terceiro; após a penhora do crédito, crédito adquirido pelo devedor contra o credor não pode ser oposto ao exequente.", "A constrição reserva o crédito ao processo executivo. O devedor não pode esvaziá-lo criando depois uma posição compensável contra o credor originário.", "Depois de penhorado crédito de uma empresa, seu devedor compra crédito contra ela e tenta compensar; o exequente pode rejeitar.", "O marco relevante é a aquisição do crédito contraposto em relação à penhora. Direitos de terceiros prevalecem sobre compensação posterior prejudicial.", "Exequente", "credor que promove execução para receber obrigação"),
    "381": row("A obrigação se extingue quando uma mesma pessoa passa a reunir as posições de credor e devedor.", "Não há sentido em alguém exigir de si próprio a mesma prestação. Essa reunião, chamada confusão, elimina o vínculo enquanto coincidem as duas qualidades.", "Devedor herda sozinho o crédito que o falecido tinha contra ele; crédito e dívida concentram-se na mesma pessoa.", "A confusão exige identidade na mesma obrigação. Ter créditos e débitos distintos contra si em patrimônios separados pode demandar análise específica.", "Confusão", "extinção obrigacional pela reunião das qualidades de credor e devedor"),
    "382": row("A confusão pode atingir toda a dívida ou apenas parte dela.", "A extensão da extinção acompanha a parcela em que credor e devedor se tornam a mesma pessoa. O saldo não abrangido continua exigível.", "Devedor adquire metade do crédito contra si; essa metade se extingue, permanecendo a outra.", "Confusão parcial não libera automaticamente coobrigados nem elimina o restante. É necessário calcular a exata participação reunida.", "Confusão parcial", "reunião das posições de credor e devedor limitada a uma fração da obrigação"),
    "383": row("Confusão envolvendo credor ou devedor solidário extingue somente a parte correspondente a essa pessoa; a solidariedade permanece no saldo.", "A reunião das posições não elimina a obrigação inteira quando há solidariedade. Deduz-se a quota pertinente, e os demais vínculos solidários continuam quanto ao valor remanescente.", "Um de três devedores solidários torna-se credor; sua quota é extinta, mas os outros continuam solidários pelo restante.", "Solidariedade não transforma a quota atingida em extinção total. O cálculo depende da posição interna do participante envolvido.", "Concorrência da parte", "limite correspondente à quota da pessoa atingida pela confusão"),
    "384": row("Se a confusão deixa de existir, a obrigação anterior e seus acessórios são imediatamente restabelecidos.", "A causa que reuniu credor e devedor pode desaparecer. Nesse caso, o vínculo volta ao estado anterior, inclusive com garantias e elementos acessórios, em vez de nascer uma obrigação nova.", "Aquisição do crédito é desfeita e as posições voltam a pessoas distintas; a obrigação e sua garantia reaparecem.", "O restabelecimento pressupõe cessação juridicamente eficaz da confusão. Direitos de terceiros e efeitos de atos intermediários podem exigir análise própria.", "Acessórios", "garantias, encargos e direitos vinculados à obrigação principal"),
    "385": row("O perdão da dívida aceito pelo devedor extingue a obrigação, desde que não prejudique terceiro.", "A remissão é negócio liberatório: depende de concordância do beneficiado e encontra limite nos direitos alheios. Com esses requisitos, o credor abre mão do crédito.", "Credor perdoa saldo de empréstimo e o devedor aceita; a dívida deixa de ser exigível.", "Remissão não pode fraudar garantia ou direito de terceiro. Também não se presume apenas de tolerância ou falta temporária de cobrança.", "Remissão", "perdão voluntário do crédito aceito pelo devedor"),
    "386": row("A entrega voluntária do instrumento particular da obrigação prova a liberação do devedor e dos coobrigados, se as partes tiverem capacidade para o ato.", "A posse devolvida do documento pelo credor funciona como prova de desoneração, desde que ele possa dispor do crédito e o devedor possa receber a vantagem.", "Credor capaz entrega espontaneamente ao devedor o contrato particular original que documentava a dívida.", "A regra é probatória e exige voluntariedade. Aplica-se ao escrito particular e não dispensa examinar fraude, incapacidade ou prova contrária relevante.", "Desoneração", "liberação do devedor e dos demais obrigados quanto ao vínculo"),
    "387": row("A devolução voluntária do bem empenhado demonstra renúncia à garantia real, mas não perdão da dívida.", "O credor pode abrir mão do penhor e conservar o crédito sem garantia. A entrega do objeto elimina a segurança real, não o dever principal de pagar.", "Credor devolve joia dada em penhor; ainda pode cobrar a dívida, agora sem essa garantia.", "Não se deve interpretar a restituição do objeto como quitação. Para extinguir o débito é necessária causa própria, como pagamento ou remissão.", "Penhor", "garantia real constituída sobre bem móvel para assegurar uma dívida"),
    "388": row("O perdão concedido a um codevedor extingue sua quota; mesmo preservada a solidariedade dos demais, o credor deve deduzir a parte perdoada.", "A remissão individual beneficia diretamente o contemplado e reduz o total cobrável dos outros. A reserva de solidariedade mantém a força da cobrança apenas sobre o saldo.", "Em dívida solidária de três quotas iguais, o credor perdoa uma; cobra dos outros somente as duas restantes.", "Perdoar um codevedor não significa necessariamente liberar todos. A redação do ato e a dedução obrigatória da quota precisam ser respeitadas.", "Parte remitida", "quota da dívida abrangida pelo perdão concedido"),
    "389": row("O inadimplemento gera responsabilidade por perdas e danos, juros, atualização monetária e honorários advocatícios; sem índice pactuado ou legal específico, aplica-se a variação do IPCA ou de seu substituto.", "A norma reúne consequências patrimoniais do descumprimento. A atualização recompõe a perda do valor da moeda, e o parágrafo único fornece critério subsidiário para escolhê-la, respeitando antes o contrato e a lei especial.", "Contrato não fixa índice e a lei aplicável também não; ao calcular a indenização, usa-se a variação do IPCA.", "O artigo não torna todo prejuízo presumido nem autoriza duplicidade de encargos. Nexo, extensão do dano, termo inicial e eventual disciplina especial continuam relevantes.", "Atualização monetária", "recomposição nominal do valor para refletir a variação do poder de compra"),
    "390": row("Na obrigação de não fazer, o inadimplemento ocorre no dia em que o devedor pratica o ato proibido.", "A violação nasce com a conduta incompatível com o dever de abstenção. Não é necessária espera por vencimento posterior para caracterizar o descumprimento daquela obrigação negativa.", "Empresa prometeu não divulgar informação e a publica; torna-se inadimplente na data da divulgação.", "É preciso que o ato esteja efetivamente abrangido pela proibição. Impossibilidade sem culpa e medidas para desfazer a conduta seguem regras próprias.", "Obrigação negativa", "dever jurídico de não praticar determinado comportamento"),
    "391": row("O patrimônio do devedor responde pelo inadimplemento das obrigações.", "Em regra, a satisfação do crédito pode alcançar bens sujeitos à responsabilidade patrimonial. A norma não significa prisão civil nem autoriza apreensão direta sem procedimento adequado.", "Credor obtém decisão e busca penhora de bem do devedor para satisfazer o débito.", "Há bens legalmente impenhoráveis, patrimônios separados e limites processuais. A expressão geral do artigo deve ser aplicada com essas proteções.", "Responsabilidade patrimonial", "sujeição de bens à satisfação coercitiva de uma obrigação"),
    "392": row("Em contrato gratuito, quem recebe o benefício responde por culpa, e quem não é favorecido, por dolo; em contrato oneroso, cada parte responde por culpa, salvo exceção legal.", "O padrão de responsabilidade varia conforme a distribuição de vantagens. A lei é menos severa com quem atua gratuitamente sem proveito próprio, exigindo intenção danosa, enquanto cobra cuidado de quem se beneficia ou participa de troca onerosa.", "Em empréstimo gratuito, a análise da responsabilidade distingue quem recebeu a utilidade de quem apenas a concedeu.", "A classificação do contrato e a posição de cada participante são indispensáveis. Lei específica pode estabelecer regime diferente.", "Contrato benéfico", "contrato gratuito que proporciona vantagem a uma parte sem contraprestação equivalente"),
    "393": row("Salvo assunção expressa do risco, o devedor não indeniza prejuízos causados por evento inevitável cujos efeitos não podia impedir.", "Caso fortuito e força maior afastam responsabilidade quando rompem a imputação do inadimplemento. As partes podem atribuir expressamente esse risco ao devedor.", "Evento inevitável destrói a prestação sem culpa; não há indenização, salvo cláusula válida que tenha transferido o risco.", "A simples alegação de imprevisto não basta. Devem ser provadas inevitabilidade, relação causal e ausência de responsabilidade assumida ou mora relevante.", "Força maior", "evento necessário cujos efeitos não podiam ser evitados ou impedidos"),
    "394": row("Há mora do devedor quando ele não paga corretamente e mora do credor quando este recusa receber conforme tempo, lugar e forma devidos.", "O atraso juridicamente relevante pode partir de qualquer lado da relação. Cumprimento inadequado às condições legais ou convencionais também caracteriza mora, não apenas demora cronológica.", "Comprador oferece pontualmente o preço no local combinado, mas o vendedor se recusa sem motivo a recebê-lo; há mora do credor.", "Mora pressupõe prestação ainda útil e possível. Inadimplemento definitivo e ausência de imputação recebem tratamento distinto.", "Mora", "atraso ou recusa imputável no cumprimento ou recebimento da prestação"),
    "395": row("O devedor em mora responde pelos prejuízos causados pelo atraso, acrescidos de juros, atualização monetária e honorários; se a demora tornar a prestação inútil, o credor pode recusá-la e pedir indenização.", "A reparação cobre consequências ligadas causalmente à mora. Quando o cumprimento tardio perde utilidade objetiva para o credor, ele não precisa aceitar a prestação e pode converter sua pretensão em perdas e danos.", "Fornecedor entrega após a data de evento já encerrado; o cliente rejeita o material inútil e cobra os prejuízos.", "A inutilidade não decorre de mero capricho: deve resultar da mora e ser demonstrável. Encargos não podem gerar reparação duplicada.", "Enjeitar", "recusar legitimamente uma prestação que perdeu utilidade por causa do atraso"),
    "396": row("Sem conduta imputável ao devedor, ele não entra em mora.", "O atraso só produz o regime da mora quando pode ser atribuído ao devedor por ação ou omissão juridicamente relevante. Impedimento não imputável afasta essa qualificação.", "Pagamento não ocorre porque o credor não fornece dado indispensável; ausente omissão atribuível ao devedor, não há mora dele.", "Ausência de mora não extingue necessariamente a obrigação. Também se deve verificar alocação contratual de riscos, cooperação e eventual mora do credor.", "Imputável", "que pode ser juridicamente atribuído à conduta de determinada pessoa"),
    "397": row("Dívida positiva, líquida e com vencimento certo coloca o devedor em mora automaticamente quando não cumprida; sem termo, exige-se interpelação judicial ou extrajudicial.", "Com data e valor determinados, o próprio vencimento constitui a mora. Se não há momento fixado, o credor precisa comunicar formalmente a exigência para marcar o atraso.", "Empréstimo vence em 10 de maio e não é pago; a mora começa no vencimento. Sem data, o credor notifica o devedor.", "A constituição automática exige os requisitos do caput. Regras especiais e a necessidade de cooperação do credor podem alterar a análise.", "Interpelação", "comunicação formal que exige o cumprimento e constitui o devedor em mora"),
    "398": row("Em obrigação decorrente de ato ilícito, a mora do responsável começa na data da prática do ato.", "A lei fixa o marco do atraso no próprio fato lesivo, sem depender de notificação posterior. Esse momento orienta os efeitos moratórios da obrigação de reparar.", "Pessoa danifica culposamente bem alheio; para a obrigação indenizatória, a mora é considerada desde o dano ilícito.", "Primeiro é necessário caracterizar o ato ilícito e a responsabilidade. O artigo define o início da mora, não resolve sozinho todos os componentes da indenização.", "Ato ilícito", "conduta contrária ao direito que causa dano e pode gerar dever de reparar"),
    "399": row("Durante a mora, o devedor responde até por impossibilidade causada por evento inevitável, salvo se provar ausência de culpa no atraso ou que o dano ocorreria mesmo com cumprimento pontual.", "O atraso transfere ao devedor o risco do evento superveniente. Ele se libera se demonstrar uma das defesas legais: mora não culpável ou inevitabilidade do mesmo resultado ainda que tivesse cumprido no tempo correto.", "Bem deveria ter sido entregue antes de enchente e é destruído durante o atraso; o devedor responde, salvo prova da exceção.", "Não basta mencionar força maior. O devedor deve demonstrar precisamente a excludente aplicável e seu nexo com o dano.", "Perpetuação da obrigação", "manutenção agravada da responsabilidade do devedor pelo risco ocorrido durante a mora"),
    "400": row("A mora do credor reduz a responsabilidade do devedor sem dolo, impõe reembolso das despesas de conservação e, havendo oscilação de valor, favorece o devedor na avaliação da coisa.", "Quem recusa injustificadamente a prestação assume consequências do atraso: paga os custos para preservar o objeto e não pode transferir ao devedor inocente os riscos normais de conservação. Entre os valores do vencimento e do recebimento, aplica-se a estimativa mais benéfica ao devedor.", "Credor recusa máquina oferecida corretamente; depois reembolsa armazenamento e recebe-a pelo valor mais favorável ao devedor.", "A exoneração não protege conduta dolosa do devedor. É necessário comprovar oferta adequada, mora do credor, despesas e eventual variação de valor.", "Mora do credor", "recusa ou atraso imputável em receber prestação oferecida corretamente"),
}
